import data from "./measurement-data.json";

// Mainnet measurement numbers for the Lab results page. The JSON is generated by scripts/sync-measurement.mjs
// from measurement/results/<date>/, and measurement.test.ts re-derives it from that folder. Nothing here is typed by hand.

export const MEASUREMENT = data;

export const pct = (n: number, of: number) => (of === 0 ? "n/a" : `${((100 * n) / of).toFixed(1)}%`);
export const int = (n: number) => n.toLocaleString("en-US");

export const classRows = () =>
  data.classes.map((c) => [c.class, int(c.accounts), pct(c.accounts, data.classified), int(c.calls), pct(c.calls, data.totalCalls)]);

export const basisRows = () =>
  data.bases.map((b) => [b.basis, b.class ?? "", int(b.accounts), pct(b.accounts, data.classified), pct(b.calls, data.totalCalls)]);

export const callsShare = (cls: string) => {
  const c = data.classes.find((x) => x.class === cls);
  return c ? pct(c.calls, data.totalCalls) : "n/a";
};
export const basisCallsShare = (basis: string) => {
  const b = data.bases.find((x) => x.basis === basis);
  return b ? pct(b.calls, data.totalCalls) : "n/a";
};
